.slide-link {
  position: relative;
  display: inline-block;
  overflow: hidden;
  text-decoration: none;
  line-height: 1;
}

.slide-link span {
  position: relative;
  display: inline-block;

  color: black;

  transition:
    transform 0.5s cubic-bezier(0.76, 0, 0.24, 1),
    color 0.5s ease;
}

.slide-link span::after {
  content: attr(data-text);

  position: absolute;
  left: 0;
  top: 100%;

  color: #ff5a5a;
}

.slide-link:hover span {
  transform: translateY(-100%);
}

a {
  color: black;
  text-decoration: none;

  transition:
    background-color 180ms cubic-bezier(0.76, 0, 0.24, 1),
    color 180ms cubic-bezier(0.76, 0, 0.24, 1);
}

a:hover {
  color: #ff8ef6;
}
/* Wrapper around each top-level nav link (e.g. "Projects").
   Stays inline-block so it sits in the same row as the other
   top-level items (Research, People, Events). */
.cg-dropdown-wrap {
  display: inline-block;
  vertical-align: top;
}

/* Submenu list.
   No longer positioned absolutely �� it takes up real space in
   the normal document flow, so when it opens, the following
   top-level items get pushed to the right / next line instead
   of being covered. */
.cg-dropdown-menu {
  display: block;
  list-style: none;
  margin: 4px 0 10px 0;
  padding: 0;

  /* collapsed by default */
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.25s ease;
}

/* open state (hover on desktop, or .cg-open class added by JS on mobile) */
.cg-dropdown-wrap.cg-open > .cg-dropdown-menu,
.cg-dropdown-wrap:hover > .cg-dropdown-menu {
  max-height: 600px; /* large enough to fit all items */
}

.cg-dropdown-menu li {
  list-style: none;
  margin: 0;
  padding: 0;
}

.cg-dropdown-menu li a {
  display: block;
  padding: 3px 0;
  white-space: nowrap;
  text-decoration: none;
  font-family: inherit;   /* same typeface as the top-level nav */
  color: inherit;
  opacity: 0.85;
}

.cg-dropdown-menu li a:hover {
  opacity: 1;
  color: #08d9cf;
}

/* Small arrow indicator next to top-level links.
   Delete this block if you don't want it. */
.cg-dropdown-wrap > a::after {
  content: "";
  display: inline-block;
  margin-left: 5px;
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-top: 5px solid currentColor;
  vertical-align: middle;
  opacity: 0.6;
}

/* Mobile: same static, in-flow behavior already applies,
   just add a touch target and small left indent. */
@media (hover: none), (max-width: 700px) {
  .cg-dropdown-menu {
    padding-left: 14px;
  }
}

